use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantMarkForDeleteAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantMarkForDeleteAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isMarkForDelete returns null on a freshly created holder.
     */
    public function testMarkForDeleteNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isMarkForDeleteAssigned());
        $this->assertNull($holder->isMarkForDelete());
    }
}
class ImplWithTenantMarkForDeleteAttributeHolderUnitTest
